using AfriWallet.Merchants.PaymentDecision.Api.Contracts;using AfriWallet.Merchants.PaymentDecision.Application.Abstractions;using AfriWallet.Merchants.PaymentDecision.Application.Commands;using AfriWallet.Merchants.PaymentDecision.Application.Policies;using AfriWallet.Merchants.PaymentDecision.Application.Services;using AfriWallet.Merchants.PaymentDecision.Infrastructure;
var b=WebApplication.CreateBuilder(args);b.Services.AddSingleton<IPaymentIntentDecisionReader,SandboxPaymentIntentDecisionReader>();b.Services.AddSingleton<IMerchantPaymentDecisionRepository,InMemoryMerchantPaymentDecisionRepository>();b.Services.AddSingleton<IMerchantPaymentDecisionAuditStore,InMemoryMerchantPaymentDecisionAuditStore>();b.Services.AddSingleton<IMerchantPaymentDecisionClock,SystemMerchantPaymentDecisionClock>();b.Services.AddSingleton<MerchantPaymentAuthorizationPolicy>();b.Services.AddSingleton<MerchantPaymentDecisionService>();var app=b.Build();const string Actor="afriwallet-merchant-payment-decision-system";app.MapGet("/health",()=>Results.Ok(new{status="Healthy",delivery="AFW-DLV-0019.4",authorizationExecutionPerformed=false,captureExecutionPerformed=false,settlementPerformed=false,payoutPerformed=false,moneyMovementPerformed=false,ledgerMutationPerformed=false}));app.MapPost("/api/v1/merchant-payments/decisions/evaluate",async(EvaluatePaymentAuthorizationRequest r,MerchantPaymentDecisionService s,CancellationToken ct)=>Results.Ok(await s.EvaluateAsync(new EvaluatePaymentAuthorizationCommand(r.PaymentIntentId,Actor),ct)));app.MapPost("/api/v1/merchant-payments/decisions/{id:guid}/step-up/complete",async(Guid id,MerchantPaymentDecisionService s,CancellationToken ct)=>Results.Ok(await s.CompleteStepUpAsync(new CompletePaymentStepUpCommand(id,Actor),ct)));app.MapPost("/api/v1/merchant-payments/decisions/{id:guid}/capture-eligible",async(Guid id,MerchantPaymentDecisionService s,CancellationToken ct)=>Results.Ok(await s.MarkCaptureEligibleAsync(new MarkCaptureEligibleCommand(id,Actor),ct)));app.MapPost("/api/v1/merchant-payments/decisions/reevaluate",async(ReevaluatePaymentAuthorizationRequest r,MerchantPaymentDecisionService s,CancellationToken ct)=>Results.Ok(await s.ReevaluateAsync(new ReevaluatePaymentAuthorizationCommand(r.PaymentIntentId,r.Reason,Actor),ct)));app.MapGet("/api/v1/merchant-payments/decisions/{id:guid}",async(Guid id,MerchantPaymentDecisionService s,CancellationToken ct)=>Results.Ok(await s.GetAsync(id,ct)));app.Run();
